def rec(y, omega, m, h, ready, tier, blocker, y_resolution, omega_resolution,
        m_resolution, m_risk, h_resolution, lineage="LOW", sources=()):
    return dict(y_gate=y, omega_gate=omega, m_gate=m, h_status=h,
                readiness=ready, target_tier=tier, blocker=blocker,
                y_resolution=y_resolution, omega_resolution=omega_resolution,
                m_resolution=m_resolution, m_leakage_risk=m_risk,
                h_resolution=h_resolution, lineage_risk=lineage,
                source_ids=list(sources))

